S=Path(__file__).resolve().parent;data=json.loads((S/'releases.json').read_text('utf-8'));rows=data['releases'];labels={'new':'新增','fix':'修正','change':'調整'};cards=[]
current_rows=[r for r in rows if r['status']=='current']
